import { ImagePipeline, type PreviewFrame } from "../src/pipeline.ts";
import { PreviewView, type Painter } from "../src/preview.ts";
import { SliderBinding } from "../src/slider.ts";

const source = { width: 8, height: 8, pixels: new Uint8Array(64).map((_, i) => 128 + i) };
const pipeline = new ImagePipeline(source);
const slider = new SliderBinding(10);

const painted: PreviewFrame[] = [];
const painter: Painter = { paint: (f) => painted.push(f) };
const view = new PreviewView(pipeline, slider, painter);

let emissions = 0;
let lastValue: number | null = null;
slider.onChange((s) => { emissions++; lastValue = s.value; });

// (2) Intermediate in-drag value changes alone trigger no preview re-render.
slider.beginDrag();
slider.setValue(0.3);
slider.setValue(0.6);
assert.equal(emissions, 0, "no emissions mid-drag");
assert.equal(painted.length, 0, "no preview re-render mid-drag");

// (1) Release: exactly one emission carrying the final value; preview re-renders.
slider.endDrag();
assert.equal(emissions, 1, "exactly one emission on drag end");
assert.equal(lastValue, 0.6, "emission carries final value");
assert.equal(painted.length, 1, "preview painted exactly once");

const expected = pipeline.renderPreview(0.6);
assert.deepEqual([...view.currentFrame()!.pixels], [...expected.pixels], "frame matches final intensity");

// New drag to a new value repaints.
slider.beginDrag();
slider.setValue(0.9);
assert.equal(painted.length, 1, "still no paint mid-drag");
slider.endDrag();
assert.equal(emissions, 2);
assert.equal(painted.length, 2);
assert.deepEqual([...view.currentFrame()!.pixels], [...pipeline.renderPreview(0.9).pixels]);

// Non-drag setValue still debounces and emits exactly once for rapid changes.
slider.setValue(0.1);
slider.setValue(0.2);
await new Promise((r) => setTimeout(r, 50));
assert.equal(emissions, 3, "debounced non-drag emit fires once");
assert.equal(lastValue, 0.2);

console.log("end-to-end slider->preview verification passed");
